import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const g=JSON.parse('{"title":"Exercise","description":"","frontmatter":{},"headers":[],"relativePath":"demos/EXERCISE.md","filePath":"demos/EXERCISE.md"}'),l={name:"demos/EXERCISE.md"};function o(s,e,i,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="exercise" tabindex="-1">Exercise <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;Exercise&quot;">​</a></h1><p>Exercises: the simplest sets, to start with.</p><ul><li><a href="#advanced_conditionals">Advanced Conditionals</a>: <code>27_advanced_conditionals.yml</code></li><li><a href="#guitarify">Guitarify</a>: <code>23_guitarify.yml</code></li><li><a href="#hello_world">Hello World</a>: <code>01_hello_world.yml</code></li><li><a href="#scale">Scales</a>: <code>04_scale.yml</code></li></ul><p><a id="advanced_conditionals"></a></p><h2 id="advanced-conditionals-27-advanced-conditionals-yml" tabindex="-1">Advanced Conditionals: <code>27_advanced_conditionals.yml</code> <a class="header-anchor" href="#advanced-conditionals-27-advanced-conditionals-yml" aria-label="Permalink to &quot;Advanced Conditionals: `27_advanced_conditionals.yml`&quot;">​</a></h2><p>Conditional Execution in six scenes. In the first, four tracks each play one note a bar, each at a different place in the bar: one in every bar, one in every second bar, one in every third bar, and one whose pitch climbs with the count of the bars, so that the counting is heard. In the second, one pattern of four chords plays eight times on one guitar, and the chain&#39;s four Guitarify generators take turns, so the same chords are strummed, then picked, then chugged, then rolled, twice round. The last three scenes show the statements a step of a pattern can hold: Mute When plays a bass fill only in every fourth bar while two notes take turns bar by bar, Restart When makes a riff start over after half a bar twice before playing whole, and Stop When ends the song after a phrase has played exactly two and a half times. Before that last scene, two registers show their Reset behavior: one reverses, so a single note walks up the scale and back down, and one overflows, so a single note visits the same five pitches in a shuffled order.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/27_advanced_conditionals.yml" target="_blank" rel="noreferrer"><code>examples/learning/27_advanced_conditionals.yml</code></a> · A minor pentatonic · 112 BPM · 3:09 · 6 scenes · 5 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">guitarify</th><th style="text-align:center;">key changes</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">registers</th><th style="text-align:center;">conditional execution</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../CHAINS">✓</a></td><td style="text-align:center;"><a href="./../generators/GUITARIFY">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../REGISTERS">✓</a></td><td style="text-align:center;"><a href="./../REGISTERS#conditional-execution">✓</a></td></tr></tbody></table><p><a id="guitarify"></a></p><h2 id="guitarify-23-guitarify-yml" tabindex="-1">Guitarify: <code>23_guitarify.yml</code> <a class="header-anchor" href="#guitarify-23-guitarify-yml" aria-label="Permalink to &quot;Guitarify: `23_guitarify.yml`&quot;">​</a></h2><p>A tour of guitar playing in twenty short scenes, each a way a guitar is played, on seven General MIDI guitars and nothing else: a country bass note and strum, picking with thumb and fingers, bluegrass crosspicking, jazz comping, a blues in open G, power chords, a surf tremolo, the folk strum, funk scratching, a singer&#39;s rolled chords, metal gallops and a twelve bar shuffle. Every pattern is only a row of chords or low notes, and the Guitarify generator of each scene does the playing, so the demo shows what its Shape and Strokes sections do to the same kind of pattern.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/23_guitarify.yml" target="_blank" rel="noreferrer"><code>examples/learning/23_guitarify.yml</code></a> · G major · 104 BPM · 3:09 · 20 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">guitarify</th><th style="text-align:center;">key changes</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../CHAINS">✓</a></td><td style="text-align:center;"><a href="./../generators/GUITARIFY">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td></tr></tbody></table><p><a id="hello_world"></a></p><h2 id="hello-world-01-hello-world-yml" tabindex="-1">Hello World: <code>01_hello_world.yml</code> <a class="header-anchor" href="#hello-world-01-hello-world-yml" aria-label="Permalink to &quot;Hello World: `01_hello_world.yml`&quot;">​</a></h2><p>The smallest set there is: a C major scale up in the first scene, down in the second, and up again in the third while a second track holds a C chord for a quarter note, every note a sixteenth. Three seconds long. Open it to see what a pattern, a track and a scene are, play it first when setting up real-time MIDI (<code>docs/MIDI_SETUP.md</code>), and record it first (<code>docs/RECORDING.md</code>).</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/01_hello_world.yml" target="_blank" rel="noreferrer"><code>examples/learning/01_hello_world.yml</code></a> · C major · 120 BPM · 0:03 · 3 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td></tr></tbody></table><p><a id="scale"></a></p><h2 id="scales-04-scale-yml" tabindex="-1">Scales: <code>04_scale.yml</code> <a class="header-anchor" href="#scales-04-scale-yml" aria-label="Permalink to &quot;Scales: `04_scale.yml`&quot;">​</a></h2><p>Every scale llamatron knows, each run up an octave and back down from D, one scene per scale, in the order of the scale picker. Use it to preview a scale before choosing one. The demo shows that a scene can set its own scale, and that a degree past the top of a scale wraps up an octave.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/04_scale.yml" target="_blank" rel="noreferrer"><code>examples/learning/04_scale.yml</code></a> · D major · 120 BPM · 3:01 · 47 scenes · 1 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">key changes</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td></tr></tbody></table>',23)])])}const m=t(l,[["render",o]]);export{g as __pageData,m as default};
